import 'package:flutter/material.dart';
import 'package:firebase_core/firebase_core.dart';
import 'package:firebase_database/firebase_database.dart';
import 'firebase_options.dart';
Future<void> main()async{WidgetsFlutterBinding.ensureInitialized();await Firebase.initializeApp(options:DefaultFirebaseOptions.currentPlatform);runApp(const BookApp());}
class BookApp extends StatelessWidget{const BookApp({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'Book Exchange',theme:ThemeData(colorScheme:ColorScheme.fromSeed(seedColor:Colors.teal),useMaterial3:true),home:const BookHome());}
class BookHome extends StatefulWidget{const BookHome({super.key});@override State<BookHome> createState()=>_BookHomeState();}
class _BookHomeState extends State<BookHome>{final ref=FirebaseDatabase.instance.ref('book_exchange');bool archived=false;Future<void> editor([String? id,Map? old])async{final title=TextEditingController(text:old?['title']??'');final author=TextEditingController(text:old?['author']??'');final course=TextEditingController(text:old?['course']??'');final price=TextEditingController(text:old?['price']??'');final result=await showDialog<bool>(context:context,builder:(x)=>AlertDialog(title:Text(id==null?'List a textbook':'Edit listing'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:title,decoration:const InputDecoration(labelText:'Book title')),TextField(controller:author,decoration:const InputDecoration(labelText:'Author')),TextField(controller:course,decoration:const InputDecoration(labelText:'Course / subject')),TextField(controller:price,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Expected price (₹)'))])),actions:[TextButton(onPressed:()=>Navigator.pop(x,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(x,true),child:const Text('Save'))]));if(result==true&&title.text.trim().isNotEmpty){final data={'title':title.text.trim(),'author':author.text.trim(),'course':course.text.trim(),'price':price.text.trim(),'archived':false,'updatedAt':DateTime.now().toIso8601String()};if(id==null){data['createdAt']=DateTime.now().toIso8601String();await ref.push().set(data);}else{await ref.child(id).update(data);}}}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('BookLoop • Exchange')),floatingActionButton:archived?null:FloatingActionButton.extended(onPressed:()=>editor(),icon:const Icon(Icons.add),label:const Text('List a book')),body:Column(children:[Padding(padding:const EdgeInsets.all(12),child:SegmentedButton<bool>(segments:const [ButtonSegment(value:false,label:Text('Available')),ButtonSegment(value:true,label:Text('Archived'))],selected:{archived},onSelectionChanged:(v)=>setState(()=>archived=v.first))),Expanded(child:StreamBuilder<DatabaseEvent>(stream:ref.onValue,builder:(c,s){if(s.hasError)return Center(child:Text('Firebase error: ${s.error}'));if(!s.hasData)return const Center(child:CircularProgressIndicator());final raw=s.data!.snapshot.value;if(raw==null)return const Center(child:Text('No listings yet'));final m=Map<dynamic,dynamic>.from(raw as Map);final rows=m.entries.where((e)=>(e.value['archived']==true)==archived).toList();if(rows.isEmpty)return const Center(child:Text('Nothing in this section yet'));return ListView.builder(itemCount:rows.length,itemBuilder:(c,i){final e=rows[i];final b=Map<dynamic,dynamic>.from(e.value);return Card(margin:const EdgeInsets.symmetric(horizontal:12,vertical:6),child:ListTile(leading:const CircleAvatar(child:Icon(Icons.menu_book)),title:Text('${b['title']??'Untitled'}'),subtitle:Text('${b['author']??''} • ${b['course']??''}\\n₹${b['price']??'Negotiable'}'),isThreeLine:true,onTap:()=>editor('${e.key}',b),trailing:PopupMenuButton<String>(onSelected:(v)async{if(v=='archive')await ref.child('${e.key}').update({'archived':!archived});if(v=='delete')await ref.child('${e.key}').remove();},itemBuilder:(_)=>[PopupMenuItem(value:'archive',child:Text(archived?'Restore':'Archive')),const PopupMenuItem(value:'delete',child:Text('Delete'))])));}));}))]));}
